import { useState } from 'react';
const pisos = ['PB', 'EPB', 'P1', 'EP1', 'P2', 'P3'];

export const AscensorPisos = ({ pisoActual, onClick }) => {
    const pos = pisos.indexOf(pisoActual);

    const activarSubir = pos < pisos.length - 1 ? 'pointer' : 'not-allowed';
    const activarBajar = pos > 0 ? 'pointer' : 'not-allowed';

    const handleSubir = () => {
        if (pos < pisos.length - 1) {
            const nuevaPos = pos + 1;
            onClick(pisos[nuevaPos]);
        }
    };

    const handleBajar = () => {
        if (pos > 0) {
            const nuevaPos = pos - 1;
            onClick(pisos[nuevaPos]);
        }
    };

    return (
        <svg
            width="283"
            height="213"
            viewBox="0 0 283 213"
            fill="none"
            style={{ width: '100%', height: 'auto' }}
            xmlns="http://www.w3.org/2000/svg"
            xmlns:xlink="http://www.w3.org/1999/xlink"
        >
            <rect width="283" height="213" fill="url(#pattern0_736_7)" />
            <circle
                onClick={handleSubir}
                style={{ cursor: activarSubir }}
                cx="244"
                cy="78"
                r="26"
                fill="transparent"
            />
            <circle
                onClick={handleBajar}
                style={{ cursor: activarBajar }}
                cx="244"
                cy="137"
                r="26"
                fill="transparent"
            />
            <defs>
                <pattern
                    id="pattern0_736_7"
                    patternContentUnits="objectBoundingBox"
                    width="1"
                    height="1"
                >
                    <use
                        xlinkHref="#image0_736_7"
                        transform="matrix(0.00115209 0 0 0.00153071 -0.151943 -0.324237)"
                    />
                </pattern>
                <image
                    id="image0_736_7"
                    width="1920"
                    height="1080"
                    preserveAspectRatio="none"
                    href="data:image/png;base64,"
                />
            </defs>
        </svg>
    );
};
